"""Parity + invariant tests for dynamic-sign normalization (mirror of the TS one)."""

import json
from pathlib import Path

import numpy as np
import pytest

from sign_ml.dynamic_normalization import (
    DYNAMIC_NORMALIZATION_ID,
    FRAME_FEATURE_DIM,
    POSE_BLOCK_LEN,
    POSE_LANDMARK_COUNT,
    UPPER_BODY_POSE_INDICES,
    normalize_frame,
    normalize_pose,
)

# Shared TS<->Python parity fixture (generated by sign_ml.golden_dynamic).
GOLDEN_FIXTURE = (
    Path(__file__).resolve().parents[2]
    / "frontend"
    / "src"
    / "recognition"
    / "fixtures"
    / "dynamic-normalization.golden.json"
)

L_SHOULDER_POS = UPPER_BODY_POSE_INDICES.index(11)
R_SHOULDER_POS = UPPER_BODY_POSE_INDICES.index(12)


def _xyz(points: list[dict[str, float]] | None) -> list[list[float]] | None:
    if points is None:
        return None
    return [[p["x"], p["y"], p["z"]] for p in points]


def _sample_pose() -> list[list[float]]:
    pose = [
        [0.5 + 0.005 * i, 0.4 + 0.006 * i, 0.002 * i]
        for i in range(POSE_LANDMARK_COUNT)
    ]
    pose[11] = [0.6, 0.5, 0.0]  # left shoulder
    pose[12] = [0.4, 0.5, 0.0]  # right shoulder
    return pose


def test_matches_shared_golden_fixture() -> None:
    fixture = json.loads(GOLDEN_FIXTURE.read_text(encoding="utf-8"))
    assert fixture["frameFeatureDim"] == FRAME_FEATURE_DIM
    for case in fixture["cases"]:
        out = normalize_frame(
            _xyz(case["pose"]),
            _xyz(case["leftHand"]),
            _xyz(case["rightHand"]),
        )
        expected = np.asarray(case["expected"], dtype=np.float64)
        np.testing.assert_allclose(out, expected, atol=1e-9, err_msg=case["name"])


def test_pose_maps_shoulder_midpoint_to_origin() -> None:
    out = normalize_pose(_sample_pose())
    midpoint = (out[L_SHOULDER_POS] + out[R_SHOULDER_POS]) / 2.0
    np.testing.assert_allclose(midpoint, [0.0, 0.0, 0.0], atol=1e-12)


def test_pose_shoulder_width_becomes_one() -> None:
    out = normalize_pose(_sample_pose())
    width = float(np.linalg.norm(out[L_SHOULDER_POS] - out[R_SHOULDER_POS]))
    assert width == pytest.approx(1.0, abs=1e-9)


def test_pose_is_translation_invariant() -> None:
    base = np.asarray(_sample_pose(), dtype=np.float64)
    shifted = base + np.array([3.0, -2.0, 1.0])
    np.testing.assert_allclose(
        normalize_pose(base), normalize_pose(shifted), atol=1e-12
    )


def test_pose_wrong_shape_raises() -> None:
    with pytest.raises(ValueError):
        normalize_pose([[0.0, 0.0, 0.0]])


def test_frame_dim_and_presence_flags() -> None:
    pose = _sample_pose()
    hand = [[0.5 + 0.02 * i, 0.5 + 0.03 * i, 0.01 * i] for i in range(21)]
    out = normalize_frame(pose, hand, None)
    assert out.shape == (FRAME_FEATURE_DIM,)
    assert out[-2] == 1.0  # left hand present
    assert out[-1] == 0.0  # right hand absent


def test_empty_frame_is_all_zeros() -> None:
    out = normalize_frame(None, None, None)
    np.testing.assert_array_equal(out, np.zeros(FRAME_FEATURE_DIM))


def test_absent_pose_block_is_zero() -> None:
    hand = [[0.5 + 0.02 * i, 0.5 + 0.03 * i, 0.01 * i] for i in range(21)]
    out = normalize_frame(None, hand, hand)
    np.testing.assert_array_equal(out[:POSE_BLOCK_LEN], np.zeros(POSE_BLOCK_LEN))


def test_normalization_id_is_stable() -> None:
    assert DYNAMIC_NORMALIZATION_ID == "pose-shoulder-hands-v1"
